 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full separators and the rectangular panels between them.
    colors = {v for row in grid for v in row if v}
    sep = next(v for v in colors if any(all(x == v for x in row) for row in grid))
    rows = [r for r, row in enumerate(grid) if all(x == sep for x in row)]
    cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    rb, cb = [-1] + rows + [h], [-1] + cols + [w]
    bands = [(rb[i] + 1, rb[i+1]) for i in range(len(rb)-1)]
    panels = [(cb[i] + 1, cb[i+1]) for i in range(len(cb)-1)]
    out = [row[:] for row in grid]

    # Objects occur as reflected pairs in neighboring panels. Infer the paired
    # panels from a pair already present, then complete missing reflections.
    for p in range(len(panels)-1):
        a0,a1 = panels[p]; b0,b1 = panels[p+1]
        if a1-a0 != b1-b0:
            continue
        width = a1-a0
        for color in colors - {sep}:
            paired = False
            for r0,r1 in bands:
                left = [[grid[r][a0+x] for x in range(width)] for r in range(r0,r1)]
                right = [[grid[r][b0+x] for x in range(width)] for r in range(r0,r1)]
                if any(v == color for row in left for v in row) and any(v == color for row in right for v in row):
                    if all(left[y][x] == right[y][width-1-x] for y in range(r1-r0) for x in range(width)):
                        paired = True
            if not paired:
                continue
            for r0,r1 in bands:
                left = [[out[r][a0+x] for x in range(width)] for r in range(r0,r1)]
                right = [[out[r][b0+x] for x in range(width)] for r in range(r0,r1)]
                has_left = any(v == color for row in left for v in row)
                has_right = any(v == color for row in right for v in row)
                if has_left and not has_right:
                    for y in range(r1-r0):
                        for x in range(width): out[r0+y][b0+x] = left[y][width-1-x]
                elif has_right and not has_left:
                    for y in range(r1-r0):
                        for x in range(width): out[r0+y][a0+x] = right[y][width-1-x]
    return out
